discrete DataCollectionAndPreprocessing
port:
    event input real StartSignal;
    event output real DataReady;
state:
    initial state WaitForDataCollection
        when entry() then
            statehold(5);
        end;
        when receive(StartSignal) then
            transition(DataCollection);
        end;
    end;

    state DataCollection
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(DataPreprocessing);
        end;
    end;

    state DataPreprocessing
        when entry() then
            statehold(15);
        end;
        when timeover() then
            transition(DataPreparationComplete);
            out
                send(DataReady, 1);
        end;
    end;

    state DataPreparationComplete
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(WaitForDataCollection);
        end;
    end;
end;
end;

discrete ModelTrainingAndPrediction
port:
    event input real DataReady;
    event output real PredictionGenerated;
state:
    initial state WaitForModelTraining
        when entry() then
            statehold(5);
        end;
        when receive(DataReady) then
            transition(ModelTraining);
        end;
    end;

    state ModelTraining
        when entry() then
            statehold(20);
        end;
        when timeover() then
            transition(ModelValidation);
        end;
    end;

    state ModelValidation
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(ModelPrediction);
        end;
    end;

    state ModelPrediction
        when entry() then
            statehold(15);
        end;
        when timeover() then
            transition(PredictionGenerated);
        end;
    end;

    state PredictionGenerated
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(WaitForModelTraining);
            out
                send(PredictionGenerated, 1);
        end;
    end;
end;
end;

discrete ResultDisplayAndAnalysis
port:
    event input real PredictionGenerated;
    event output real ReportGenerated;
state:
    initial state WaitForPredictionResult
        when entry() then
            statehold(5);
        end;
        when receive(PredictionGenerated) then
            transition(ResultDisplay);
        end;
    end;

    state ResultDisplay
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(ResultAnalysis);
        end;
    end;

    state ResultAnalysis
        when entry() then
            statehold(15);
        end;
        when timeover() then
            transition(ReportGeneration);
        end;
    end;

    state ReportGeneration
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(WaitForPredictionResult);
            out
                send(ReportGenerated, 1);
        end;
    end;
end;
end;

